    require(q['positive_paragraph_count']==16 and q['negative_count']==len(q['negative_cases'])==75 and all(c['rejected'] for c in q['negative_cases']) and len(q['row_count_reasons'])==4 and q['all_base_QA_diagnostics_preserved_one_exact_R35_article_classification'],'policy obligations')
    require(sum(bool(r['row_count_reason']) for r in doc['records'])==4,'four exact row reasons')
    warning=dict(severity='warning',code='weak-line-ending',message="line 2 ends with weak wrap word 'the'")
    special=next(r for r in doc['records'] if r['source_record_index']==35)
    require(special['exact_reviewed_base_warnings']==[warning] and special['qa_waivers']==['weak-line-ending'] and special['qa_waiver_reason'] and special['formatted_markup'].split('{LB}')[1]=='I think I heard it was seen in the' and special['formatted_markup'].split('{LB}')[2]=='far reaches of the Mediterranean.','sole exact complete-word article classification')
    require(all(not(r['exact_reviewed_base_warnings'] or r['qa_waivers'] or r['qa_waiver_reason']) for r in doc['records'] if r['source_record_index']!=35),'no other warning orwaiver')
    names=load(doc['speaker_name_review']);require(all(names[k] for k in ['both_actual_final_English_personal_names_complete','two_contextual_progressive_names_retained_no_assets_or_duplicate_credit','both_null_middle_fields_andsame_text_full_getters_preserved','no_surname_nationality_occupation_kinship_or_rank_inferred','full_catalogue_UI_unvisited','full207_name_role_alias_andearlier_name_review_open','legacy_item99_title_ambiguity_unapproved','legacy_item99_Medicine_title_ambiguity_unapproved_andnot_changed','progressive_header_display_only_not_full_catalogue_UI_approval','no_new_name_or_dialogue_credit']),'name consumers andscope')
