    item=load(doc['source_named_item_binding']);require(all(item[k] for k in ['source_physician_spelling_Herophilus_supported_by_exact_item_name_andlegacy_designation','no_new_physician_nationality_gender_biography_or_modern_history_fact_inferred','source_medical_book_not_drug_or_runtime_FI_substitution','legacy_Herophilus_Medicine_title_is_exact_current_asset_not_new_editorial_approval','broader_item99_title_consumer_review_lead_medical_book_vs_medicine_ambiguity','reported_sailor_fatigue_management_not_cure_orconfirmed_mechanic','no_item_or_actor_asset_change_or_duplicate_credit','no_inventory_card_orcomplete_item_mechanic_orother_consumer_approval','full207_name_role_alias_andearlier_consumer_review_remains_open']),'medical book andunapproved title scope')
    r=item['source_named_item'];require((r['record_ID'],r['Japanese'],r['English'],r['source_terminated_hex'],r['current_terminated_hex'])==('DK4_ITEM_POINTER_099','ヘロフィロスの医学書',"Herophilus' Medicine",'8377838d83748342838d835882cc88e38a778f9100','4865726f7068696c757327204d65646963696e6500'),'exact legacy item99');fields(r)
    require((r['pointer_field'],r['source_storage_offset'],r['current_storage_kind'],r['current_storage_offset'])==(1174360,1436788,'static-current-ARM9',1436572) and r['current_native_item_getter_card_bounds_mechanics_and_all_other_consumers_not_reviewed_here'],'item99 exact static storage andunapproved other consumers')
    np=load(doc['native_name_proof']);require(np['name_literal_alignment_count']==24 and np['complete_name_component_plane_count']==len(np['name_planes'])==6 and sum(len(r['native_alignment']['cases']) for r in np['name_planes'])==24 and {r['text'] for r in np['name_planes']}=={'Lil Argot','Carlo Sinat','Lil','Argot','Carlo','Sinat'} and np['source_personal_fields_Lil_Argot_Carlo_Sinat_match_both_original_getters'] and np['no_surname_nationality_occupation_or_scene_location_inferred_from_secondary_field'] and np['all_first_internal_final_name_glyphs_and_zero_ink_flushes_complete'] and np['no_name_asset_or_duplicate_credit'],'six fresh name planes24 native alignments')
    entry=load(doc['source_entry_proof']);require(sha(Path(doc['source_entry_proof']).read_bytes())==doc['source_entry_proof_sha256'] and entry['original_source_EV2_and_action_table_exact'] and [(r['event_ID'],r['script_block'],r['action_index'],r['must_be_completed'],r['must_not_be_completed']) for r in entry['selected_B231_source_events']]==[(231,231,232,[],[])],'original231 hasno explicit requires or excludes;not forced eligibility')

    a,l=load(doc['actual_English_proof']),load(doc['later_scope_proof']);o=mapping['observed_comparison_contract']
    measured=dict(source_exit=a['source_exit_frame'],English_exit=a['exit_frame'],normal_port=a['normal_port_sample_frame'],body_holds=a['actual_complete_body_holds'],name_holds=a['actual_complete_name_holds'],command_difference_rows=len(a['command_comparison_differences']),duration_changes=len(a['command_duration_changes']),later_samples=len(a['later_sampled_whole_frame_comparisons']),later_RGB_differences=len(l['later_sampled_RGB_differences']),component_equality=l['five_native_component_equality'],captains=l['captain_IDs'],PRNG_seeds=l['final_PRNG_seeds'],following_B120_ends=[r['B120_end_frames'] for r in l['following_B120']])
    require(measured==o==seal['observed_comparison_contract'],'all actual measured comparisons preserved')
