    require(a['actual_native_pages']==len(a['actual_page_panels'])==16 and not a['incomplete_sampled_body_holds'] and len(a['semantic_upper_portrait_pairs'])==16 and not a['page_transitions'] and all(a[k] for k in ['all16_single_original_native_pages_verified','initialized_B22_not_natural_event231_original_location_earned_progress_full_effects_route_orhardware','no_roles_roster_funds_conditions_RNG_results_RAM_code_battery_or_savestate_forced','no_full_RAM_every_intermediate_frame_future_sequence_broad_simulation_orcausal_claim','full207_name_role_alias_andearlier_editorial_scope_open','both_source_personal_names_preserved','all_following_resident_payloads_verified_against_actual_SC0_to_SC3_bank','full_catalogue_UI_unvisited','legacy_item99_Medicine_title_ambiguity_unapproved','progressive_header_approval_only_no_name_asset_change']),'actual pages andcoverage limits')
    plan=load(next(p for p in a['evidence'] if Path(p).name=='run_plan.json'));fixture=load(a['fixture']);require(plan['source_event231_not_naturally_selected'] and plan['displayed_original_source_block']==231 and fixture['fixtures'][0]['source_block']==231 and fixture['initialized_Amsterdam_B22_not_natural_event231_location_or_earned_progress'],'actual B231 entry scope')
